# 73. 矩阵置零 — 第一行第一列充当标记
# 时间 O(mn)，额外空间 O(1)。
# 核心思想：用第一列标记整行，用第一行标记整列；两个布尔值另记第一行、第一列原本是否含零。

import sys

# 完整 ACM 入口：读入题面约定的数据，计算答案，再写标准输出。
def solve():
    # 按本题输入格式读取这一行；split 按空白分隔，整数用 int 转换。
    m, n = map(int, input().split())
    # 按空白分隔这一行并转成整数；空行可解析为空序列。
    matrix = [list(map(int, sys.stdin.readline().split())) for _ in range(m)]
    # 第一行第一列要用作标记，先保存它们原本是否含零。
    first_row = any((x == 0 for x in matrix[0]))
    first_col = any((row[0] == 0 for row in matrix))
    for i in range(1, m):
        for j in range(1, n):
            # 只标记，不立即改整行，避免新零污染判断。
            if matrix[i][j] == 0:
                matrix[i][0] = matrix[0][j] = 0
    for i in range(1, m):
        for j in range(1, n):
            if matrix[i][0] == 0 or matrix[0][j] == 0:
                matrix[i][j] = 0
    # 最后处理边界，此时内部已根据原始标记完成。
    if first_row:
        matrix[0] = [0] * n
    if first_col:
        for row in matrix:
            row[0] = 0
    for row in matrix:
        # 只输出题目要求的结果；调试信息请写入 sys.stderr。
        print(*row)
# 直接运行此文件时执行 solve；不需要在线判题平台提供 Solution 类。
if __name__ == '__main__':
    solve()

