# 138. 随机链表的复制 — 旧节点到新节点的映射
# 时间 O(n)，额外空间 O(n)。
# 核心思想：第一遍给每个旧节点创建唯一新节点；第二遍用映射翻译 next 与 random 的目标。

import sys
sys.setrecursionlimit(100000)

# 一个节点保存数值以及指向其他节点的引用；引用不同于数值本身。
class Node:

    def __init__(self, val=0, next=None):
        self.val, self.next = (val, next)

# 按输入顺序尾插建链。虚拟头不输出，返回第一个真实节点。
def build(values):
    dummy = tail = Node()
    for v in values:
        tail.next = Node(v)
        tail = tail.next
    return dummy.next

# 沿 next 取值输出；仅用于无环链表，空链输出 EMPTY。
def show(head):
    values = []
    while head:
        values.append(head.val)
        head = head.next
    if values:
        # 只输出题目要求的结果；调试信息请写入 sys.stderr。
        print(*values)
    else:
        # 只输出题目要求的结果；调试信息请写入 sys.stderr。
        print('EMPTY')

# 完整 ACM 入口：读入题面约定的数据，计算答案，再写标准输出。
def solve():
    # 读取一个整数，含义与范围见题目输入格式。
    n = int(input())
    # 按空白分隔这一行并转成整数；空行可解析为空序列。
    rows = [list(map(int, sys.stdin.readline().split())) for _ in range(n)]
    nodes = [Node(v) for v, _ in rows]
    for i, (_, right) in enumerate(rows):
        if i + 1 < n:
            nodes[i].next = nodes[i + 1]
        else:
            nodes[i].next = None
        if right >= 0:
            nodes[i].random = nodes[right]
        else:
            nodes[i].random = None
    # 先建齐全部新节点，支持 random 指向尚未访问的后方节点。
    clones = {node: Node(node.val) for node in nodes}
    for node in nodes:
        # 用旧→新映射翻译指针，不能保留指向旧链表的边。
        clones[node].next = clones.get(node.next)
        clones[node].random = clones.get(node.random)
    copied = [clones[node] for node in nodes]
    # 输出格式用下标表达 random，不打印对象地址。
    index = {node: i for i, node in enumerate(copied)}
    # 只输出题目要求的结果；调试信息请写入 sys.stderr。
    print(n)
    for node in copied:
        # 只输出题目要求的结果；调试信息请写入 sys.stderr。
        print(node.val, index.get(node.random, -1))
# 直接运行此文件时执行 solve；不需要在线判题平台提供 Solution 类。
if __name__ == '__main__':
    solve()

