# 148. 排序链表 — 链表归并排序
# 时间 O(n log n)，递归空间 O(log n)。
# 核心思想：快慢指针切成两半，递归排好各半，再像 21 题一样合并两个有序链表。

import sys
sys.setrecursionlimit(100000)

# 一个节点保存数值以及指向其他节点的引用；引用不同于数值本身。
class Node:

    def __init__(self, val=0, next=None):
        self.val, self.next = (val, next)

# 按输入顺序尾插建链。虚拟头不输出，返回第一个真实节点。
def build(values):
    dummy = tail = Node()
    for v in values:
        tail.next = Node(v)
        tail = tail.next
    return dummy.next

# 沿 next 取值输出；仅用于无环链表，空链输出 EMPTY。
def show(head):
    values = []
    while head:
        values.append(head.val)
        head = head.next
    if values:
        # 只输出题目要求的结果；调试信息请写入 sys.stderr。
        print(*values)
    else:
        # 只输出题目要求的结果；调试信息请写入 sys.stderr。
        print('EMPTY')

# 完整 ACM 入口：读入题面约定的数据，计算答案，再写标准输出。
def solve():
    # 读取一个整数，含义与范围见题目输入格式。
    n = int(input())
    # 按空白分隔这一行并转成整数；空行可解析为空序列。
    head = build(list(map(int, sys.stdin.readline().split())))

    def merge(head_a, head_b):
        dummy = tail = Node()
        while head_a and head_b:
            if head_a.val <= head_b.val:
                tail.next, head_a = (head_a, head_a.next)
            else:
                tail.next, head_b = (head_b, head_b.next)
            tail = tail.next
        tail.next = head_a or head_b
        return dummy.next

    def sort(node):
        # 长度 0/1 无需再切分，是递归终点。
        if not node or not node.next:
            return node
        slow, fast = (node, node.next)
        while fast and fast.next:
            slow, fast = (slow.next, fast.next.next)
        right = slow.next
        # 必须切断，否则左子问题长度不会缩小。
        slow.next = None
        # 先排好两半，再合并，递归保证子问题有序。
        return merge(sort(node), sort(right))
    show(sort(head))
# 直接运行此文件时执行 solve；不需要在线判题平台提供 Solution 类。
if __name__ == '__main__':
    solve()

