# 4. 寻找两个正序数组的中位数 — 在短数组二分分割线
# 时间 O(log(min(n,m)+1))，额外空间 O(1)。
# 核心思想：左右两部分数量固定，让左边有 ceil((n+m)/2) 个数。二分短数组分到左边的个数 i，另一数组个数 j 自动确定。

import sys

# 完整 ACM 入口：读入题面约定的数据，计算答案，再写标准输出。
def solve():
    # 按本题输入格式读取这一行；split 按空白分隔，整数用 int 转换。
    n, m = map(int, input().split())
    # 按本题输入格式读取这一行；split 按空白分隔，整数用 int 转换。
    first = list(map(int, input().split()))
    # 按本题输入格式读取这一行；split 按空白分隔，整数用 int 转换。
    second = list(map(int, input().split()))
    # 只二分短数组，保证另一条分割线不会越界。
    if n > m:
        first, second, n, m = (second, first, m, n)
    left, right, half = (0, n, (n + m + 1) // 2)
    while left <= right:
        i = (left + right) // 2
        # 左侧总数固定，第二条切分线由第一条唯一决定。
        j = half - i
        if i:
            first_left = first[i - 1]
        else:
            first_left = float('-inf')
        if i < n:
            first_right = first[i]
        else:
            first_right = float('inf')
        if j:
            second_left = second[j - 1]
        else:
            second_left = float('-inf')
        if j < m:
            second_right = second[j]
        else:
            second_right = float('inf')
        # 左侧有值跨界过大，需要把短数组切分线左移。
        if first_left > second_right:
            right = i - 1
        # 反向跨界说明短数组左侧还不够多，切分线右移。
        elif second_left > first_right:
            left = i + 1
        else:
            # 只输出题目要求的结果；调试信息请写入 sys.stderr。
            print(max(first_left, second_left) if (n + m) % 2 else (max(first_left, second_left) + min(first_right, second_right)) / 2)
            return
# 直接运行此文件时执行 solve；不需要在线判题平台提供 Solution 类。
